def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Dividers are full uniform lines in a color other than the background.
    hr = [r for r in range(h)
          if len(set(grid[r])) == 1 and grid[r][0] != bg]
    vc = [c for c in range(w)
          if len({grid[r][c] for r in range(h)}) == 1
          and grid[0][c] != bg]

    def bands(size, cuts):
        result, start = [], 0
        for x in cuts:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < size:
            result.append((start, size))
        return result

    rb, cb = bands(h, hr), bands(w, vc)
    tiles = []
    for r0, r1 in rb:
        for c0, c1 in cb:
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1)
                     for c in range(c0, c1)
                     if grid[r][c] != bg]
            tiles.append((r0, r1, c0, c1, cells))

    # Pick the tile with the most foreground cells as the repeating pattern.
    source = max(tiles, key=lambda t: len(t[4]))
    ph = source[1] - source[0]
    pw = source[3] - source[2]
    pattern = source[4]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1, _ in tiles:
        if r1-r0 == ph and c1-c0 == pw:
            for dr, dc, color in pattern:
                out[r0+dr][c0+dc] = color
    return out
